    { k: "その他", w: "皮膚の診、桂枝加黄耆湯の證のごとく正気の宣暢しかたし（表虚肌膚の診）", src: "本文", koma: "277R・278L" },
    { k: "その他", w: "両乳の下から臍の上まで腹の幅いっぱいの横長の藍（上腹部全体）", src: "図", koma: "276L" }
